from pathlib import Path
import re,json
ROOT=Path(__file__).resolve().parent.parent
facts=[]
def f(title,body,sources,locals=()):
    n=42+len(facts); fid=f'F{n:03d}'
    facts.append(dict(id=fid,title=title,body=body,sources=sources,locals=list(locals)))
    return fid
def section(name): facts.append(dict(section=name))
# Fact numbering is assigned separately below so section entries do not consume IDs.
def add(title,body,sources,locals=()):
    fid=f'F{42+sum("id" in x for x in facts):03d}'
    facts.append(dict(id=fid,title=title,body=body,sources=sources,locals=list(locals)))
    return fid
section('D03 — SHWD: головы в касках и без касок')
add('SHWD: происхождение и заявленные counts', '''**Документ/заявление, прочитано.** README: 7,581 images; 9,044 helmet-wearing positive objects; 111,514 normal-head negatives. Positive images — Google/Baidu, часть normal heads — SCUT-HEAD; ручной LabelImg/VOC. Это авторские object totals, не наш полный count XML. Loader `CLASSES=['hat','person']` имеет order 0/1, но VOC хранит текстовые имена. Literal `person` в этой задаче означает голову, а не тело. SHWD/SHW и SHD 5,000 нельзя отождествлять по сокращению.''', ['S009','S011'], ['W1-03-F01','W1-03-F02','W1-09-F01'])
add('SHWD: реальный архив и split membership', '''**Наша проверка directory и полученных TXT.** ZIP total 1,117,970,537 bytes по Content-Range; 15,171 entries, 7,581 XML и 7,581 JPG, unmatched stems 0. У media 7,571 `.jpg` и 10 `.JPG`. Actual split files: train 5,457, val 607, test 1,517, trainval 6,064; train/val/test попарно disjoint, trainval=train+val. Не поставлены camera/session IDs. Получены directory, четыре split файла, 20 XML и восемь JPEG; whole ZIP SHA256/revision неизвестны. Нет найденных README/LICENSE/terms members. Directory pairing не означает full decode.''', ['S010'], ['W2-05-F01','W2-05-F02','W1-15-F01'])
add('SHWD: actual XML и visual head geometry', '''**Наша targeted проверка.** 20 XML содержат 214 objects: 24 `hat`, 190 `person`. В восьми paired JPEG все decoded W/H совпали с XML, 127 person/14 hat boxes. `000000.jpg` 947×1421, hat `[60,66,910,1108]` охватывает каску и голову/лицо; `001477.jpg` 955×1300 — тоже helmeted head со stock watermark. `part2_000069.jpg` 901×362 — коллаж трёх портретов; `part2_000761.jpg` 626×417 — семь касок на головах строителей. `PartA_00063/00535/00772` — classroom views 1091×612/1063×600/1043×575, с 4/54/67 literal person boxes на головах. `000993.jpg` 720×405 — street view с 2 person/2 hat. Это подтверждает head geometry и смешанный web/classroom domain, не обычные шапки/переносимые каски во всём наборе. XML filename/path бывает устаревшим: PartA_00772 содержит `772.jpg`; join по actual memberstem с сохранением raw fields. VOC integer xyxy; origin/inclusive convention не установлен.''', ['S009','S010'], ['W2-05-F03','W2-05-F04','W2-05-F05'])
add('SHWD: mapping, rights и роль', '''**Вывод/неизвестно.** Безопасная provisional карта: `shwd:person -> normal_head_region`; `shwd:hat -> helmeted_head_region`. Не смешивать с full-person и helmet-object-only boxes. Correct fit/ordinary hat/carried helmet policy не установлен. MIT root LICENSE — software/associated documentation; SCUT upstream academic-research-only и поисковые фото имеют отдельные ограничения. Весь SHWD не объявляется MIT. Условный head donor; CHV не независимый holdout после него. Exact parent overlaps требуют E006, scope действий — E014/Q003/Q010.''', ['S009','S010','S011'], ['W1-03-F03','W1-03-F04','W1-10-F03'])
section('D04 — CHV: Color Helmet and Vest')
add('CHV: documented lineage и объём', '''**Документ/author claim.** Статья §2.3: из примерно 10,000 изображений GDUT-HWD и SHWD отобрано 1,330 images/9,209 instances; новые vest/color labels размечены LabelImg и проверены другим исследователем. Выбирались construction backgrounds, позы, ракурсы, дистанции. Random split 1,064/133/133. Это selection+reannotation, не 1,330 новых независимых scenes. Exact image crosswalk не получен; для запрета предполагать независимость parent/child достаточно прямого author lineage.''', ['S012'], ['W1-03-F05','W1-03-F07','W1-09-F02'])
add('CHV: проверенная карта артефакта, формат и splits', '''**Документ артефакта/наша directory проверка.** ZIP 439,733,771 bytes; без `__MACOSX/` содержит 1,330 JPG/1,330 TXT stems, unmatched 0. AppleDouble `._*` не labels. Archive README: `0 person`, `1 vest`, `2 blue helmet`, `3 red helmet`, `4 white helmet`, `5 yellow helmet`; статья сокращает последние до blue/red/white/yellow. YOLO `<class> <x_center> <y_center> <width> <height>`, normalized по W/H, center не top-left. Actual train 1,064/valid 133/test 133, попарные intersections 0. Полный image decode/9,209 object recount не выполнен. Отдельного LICENSE/terms notice нет.''', ['S012','S013'], ['W2-06-F01','W2-06-F02','W2-06-F03','W1-03-F06','W1-15-F02'])
add('CHV: actual sample и неполная absence supervision', '''**Наша проверка 27 TXT/4 JPEG.** 194 objects: person 77, vest 48, blue 10, red 11, white 33, yellow 15; unknown IDs/bad five-column rows/out-of-[0,1] values 0. Четыре пары: ppe_0027 660×372, ppe_0071 1000×762, ppe_0183 800×528, ppe_0311 1064×1300; 37 boxes (13 person,11 vest,10 white,1 yellow,1 red,1 blue). Person — тело/видимая часть, helmet colors — каска, vest — одежда/торс с reflective strips; не любая безрукавка. Есть portrait/stock construction images. В ppe_0183 человек без явной каски имеет person box, но no_helmet class/status нет: кандидат доразметки, не exhaustive negative GT. Relation IDs и correctness не заданы. Sample выбран ради coverage, не error-rate estimate.''', ['S012','S013'], ['W2-06-F04','W2-06-F05','W2-06-F06'])
add('CHV: разрешительный statement и практическая роль', '''**Документ/вывод.** README “open for free use” и citation — разрешительное заявление с нераскрытым modification/republication/commercial scope, не стандартная blanket media license. Archive README описывает format, не устраняет upstream SHWD/GDUT conditions. Conditional vest/color donor при соответствующем кейсе; не no_helmet donor по missing labels и не independent cross-dataset test. Малый actual artifact снял access/map gate, полнота и права остаются Q003/Q010, E005/E006/E014.''', ['S012','S013'], ['W1-03-F08','W1-10-F04'])
section('D05 — SHEL5K: multi-geometry SHD reannotation')
add('SHEL5K: parent, manifest и полный XML слой', '''**Документ/наша проверка.** Mendeley v1 23.04.2021, parent SHD `andrewmvd/hard-hat-detection`: те же 5,000 images, расширение 3→6 classes/исправление пропусков по статье. Metadata: 5,000 XML+5,000 PNG, stem sets match. Сумма XML 19,154,616 bytes; PNG 1,310,436,038 bytes — metadata sizes, не compressed ZIP. Получены все 5,000 XML, каждый SHA256 совпал с author metadata; PNG получены семь (3 W1+4 W2), не весь 1.3 GB. Folder API важен: пустой root files [] не отсутствие вложенных файлов. Exact API/folder IDs и content download URLs сохранены S015.''', ['S014','S015','S016'], ['W1-03-F09','W1-09-F03','W1-15-F03','W1-15-F04','W2-07-F01'])
add('SHEL5K: exact literals/counts и объяснение 75,570/75,578', '''**Наша полная structural проверка XML.** 75,578 objects = `helmet`19,252 + `head_with_helmet`16,048 + `person_with_helmet`14,767 + `face`14,135 + `head`6,120 + `person_no_helmet`5,248 + unexpected `person`8. Шесть advertised literals дают ровно paper 75,570, все six-class counts воспроизведены. Card 75,578 подтверждено payload. Это объясняет арифметику, не author intention seventh literal. Numeric IDs отсутствуют в VOC: производный loader map назначается явно. Parse failures/empty/actual filename-stem mismatch/hash mismatch 0.''', ['S014','S015','S016'], ['W2-07-F02'])
add('SHEL5K: full geometry, размеры и flags', '''**Наша проверка.** Integer range `0<=xmin<xmax<=W`, `0<=ymin<ymax<=H`: нарушений 0; это не установление точного VOC origin/inclusive convention. Declared dimensions: 416×416 —2,192; 416×415 —2,461; 415×416 —324; 415×415 —23. Flags `(truncated,difficult)`=(0,0)69,531 и (1,0)6,047, difficult везде 0. Нельзя считать все изображения 416-square или все примеры простыми по difficult=0. Остальные 4,993 PNG hashes/decode не проверены. Source XML содержит несколько different geometry units.''', ['S016'], ['W2-07-F04'])
add('SHEL5K: подтверждённые object/head/person extent', '''**Наша XML/paired visual проверка.** hard_hat_workers0 helmet `[360,118,406,149]`, head_with_helmet `[360,118,406,175]`; 1000 person_with_helmet `[249,92,416,311]`, helmet `[327,91,409,147]`. W2 hard_hat_workers1005 416×415/20 objects содержит explicit person_no_helmet у наклонившегося работника и helmeted persons; 2743 416×416/104 objects — плотная группа, partial heads/faces. Boxes человека отдельно от головы, лица, предмета. Person-state class кодирует observed attribute, но отдельного relation ID между boxes нет; correct fastening не доказан. Это targeted semantic sample, не full completeness audit.''', ['S014','S015','S016'], ['W1-03-F10','W1-03-F11','W1-12-F01','W2-07-F06'])
add('SHEL5K: eight extra person — точные locators и quarantine', '''**Наша full XML/targeted visual проверка.** `1016.xml`: `[75,125,232,325]`,`[256,105,284,176]`; `1303.xml`: `[87,94,211,374]`,`[242,133,370,378]`; `1571.xml`: `[325,130,393,329]`,`[380,139,416,318]`; `1595.xml`: `[211,74,262,251]`; `380.xml`: `[259,33,335,286]` (все с prefix hard_hat_workers). Только 1016/1303 дополнительно просмотрены paired. В1016 закрытая/неразличимая голова и tiny background worker; в1303 один worker явно в жёлтой каске, другой со спорным головным убором/без ясной каски. Не map all8→nohelmet или helmeted. Сохранить `raw_person_unresolved`, quarantine из six-class loss или вручную доразметить с reason log. Семантику оставшихся четырёх objects не угадывать, originals не удалять.''', ['S016'], ['W2-07-F03','W2-07-F05'])
add('SHEL5K: split/completeness/rights и роль', '''**Документ/неизвестно/вывод.** Completed missing labels/partial helmet-face annotation — author claims, не наш полный semantic audit. Random 4,000/1,000 описан размерами, filename membership не найден в pinned repo (только README), Mendeley manifests или XML fields. Не выдумывать official random seed. Ordinary hat/carried helmet/correct-fit protocol не установлен. Mendeley CC BY-NC3.0, не SA; upstream photos отдельный слой. SHD после SHEL5K не independent holdout. Conditional donor раздельных helmet/head/person-state геометрий; E004/E006/E014, Q010/Q011.''', ['S014','S015','S016'], ['W1-03-F12','W1-03-F13','W1-10-F05','W2-07-F07','W2-07-F08'])
section('D06 — CPPE-5: original COCO, HF и респираторный gap')
add('CPPE: medical web domain и annotation protocol', '''**Документ/заявление.** Paper §§3–4: преимущественно Flickr, меньше Google Images, medical/non-iconic photographs; real-life не fixed CCTV. Рассматривали семь categories, respirator/shoe cover исключили из final из-за недостатка rich annotated examples; full-facepiece respirator не входил даже в исходный список. Два volunteers независимо размечают, третий согласует, verification; exhaustive claim относится к пяти final classes. Это не отсутствие всех респиратороподобных объектов внутри Mask и не GT industrial correctness/removal.''', ['S020'], ['W1-04-F01','W1-04-F03','W1-11-F07'])
add('CPPE: exact release и ограниченный tar retrieval', '''**Наша проверка.** v0.1.0 published14.12.2021 19:20:05UTC, tag commit `c18d33dd33230c601c62f944df2626cd73412a79`; dataset.tar.gz metadata238,482,705bytes, HTTP Last-Modified15.04.2023 отдельно. v0.2.0 published15.04.2023 без assets. Получен Range prefix8,388,608bytes; stream прочитал полные train.json690,419bytes/test.json30,993bytes и два PNG. Это не полный tar manifest/MD5 validation. README MD5 `f4e043f983cff94ef82ef7d57a879212` не проверен. Old tree request по tag404 заменён successful exact-commit tree.''', ['S021'], ['W1-04-F07'])
add('CPPE: original counts, exact categories и HF shift', '''**Наша полная annotation проверка/документ.** Original train1,000 image records/4,491 annotations, test29/207, total1,029/4,698. Это records, не full media decode. Original IDs1 Coverall,2 Face_Shield,3 Gloves,4 Goggles,5 Mask; HF0–4 в том же порядке. COCO bbox xywh pixels; HF objects{id,area,bbox,category}, image_id,width,height, без relation/track/state. Published full object counts: Coverall1,197,Face_Shield447,Gloves1,343,Goggles407,Mask1,304 — author Table3. Category underscores и ID shift сохранять. Нельзя присвоить всем COCO exports один zero-based map без categories.''', ['S020','S021','S023'], ['W1-04-F02','W1-11-F08','W1-12-F06','W2-08-F01'])
add('CPPE: original↔HF test29 annotation lineage', '''**Наша выполненная проверка.** Все29 test image IDs, declared dimensions и category+bbox multisets совпали после `HFcategory+1 -> originalcategory`; join по image_id, не row order. HF test objects207:45 Coverall/17 Face_Shield/61 Gloves/32 Goggles/52 Mask. Original PNG↔HF JPEG byte/pixel identity не проверена. Paper experiments говорит1,029 training + another100 testing; это не доказанный публичный1,129 archive. Для данного artifact protocol1,000/29; состав дополнительных100 остаётся неизвестным Q012. Test29 мал для редких states.''', ['S020','S021','S023'], ['W1-04-F04','W1-04-F05','W2-08-F02'])
add('CPPE: source inventory и права annotations', '''**Наша bounded проверка/датированный author statement.** Original COCO root только images,type,annotations,categories; image fields file_name,height,width,id, нет source URL/author/license/root licenses. Exact release git tree/assets и HF не дали per-image inventory, хотя paper§3.2 его описывает. Нельзя говорить, что metadata не существует: остальная часть tar/авторы не проверены. Issue6 comment29.03.2022 explicitly licenses code+annotations Apache2.0 и отделяет copyright images/Flickr conditions. W1 “Apache only code, labels unknown” уточняется этим более конкретным statement. HF license unknown относится к dataset целиком. Нужен numeric image_id→source/author/license join; media blanket clearance/weights не следует из annotation grant.''', ['S020','S021','S022','S023'], ['W2-08-F03','W2-08-F05','W1-10-F06'])
add('CPPE: Mask subtype и конкретные artifact problems', '''**Наша targeted visual проверка.** HF1012 1280×720 Mask `[369,271,516,438]` — эластомерная полумаска с фильтрами/ремнями;1013 1920×1088 — формованная фильтрующая полумаска, goggles/coverall/gloves. Original15.png943×663 совпадает declared: видны три masked people, в COCO только две Mask bbox ids114/115 — кандидат partial labels, не full error rate. Exactjoin762.png→image_id762 дал actual2246×1498 против declared1200×1200, COCO три Mask boxes: **quarantine coordinate/version mismatch**, не подтверждённая GT pair и не основание молча rescale. Train762 не входит test29 scale audit. Наш subtype по виду — не author subtype GT/сертификация/fit test.''', ['S021','S023'], ['W1-04-F06','W1-11-F09','W2-08-F04'])
add('CPPE: per-class scale и практическая роль', '''**Наша проверка/вывод.** Только HF test29/207, min-axis native→условный640 q10/q50/q90: Coverall45 `102.8/300/525.4 ->95.02/196/327.25`; Face_Shield17 `67/122/316.6 ->40.35/88/184.02`; Gloves61 `34/59/194 ->22/37.33/77`; Goggles32 `24.2/40/161.7 ->22.42/29.5/58.3`; Mask52 `24/54/210.8 ->21.45/38.78/74.12`. Test OOB0 в declared frames. Image1023 Gloves23×15 при600×400→24.53×16, image1022 Mask25×28: не весь CPPE крупноплановый. Conditional object donor Goggles/Face_Shield/broad Mask, после subtype/rights audit. Для industrial respirator нужен новый visibility/worn/removed/incorrect/unknown/person-association слой; missing box не no_respirator. Полные width/height/area/min-axis quantiles S048, E004/E005/E008/E012/E014.''', ['S020','S021','S023','S048'])
section('D07 — Smoker Detection и surveillance smoking/calling')
add('Smoker: payload, splits, decode и exact duplicates', '''**Наша проверка.** RAR65,575,997bytes, SHA256 `2b0ef67ec714a507cff7248ef7f3d7bbdb4c4e00adc8e309cfac02cd2b6e5d18` совпал API.1,120JPG+4directories, Training716(358+358),Validation180(90+90),Testing224(112+112). Все1,120 Pillow load decoded250×250; decoded RGB SHA256 exact duplicate groups0. Filename smoking_/notsmoking_ — image class, не cigarette bbox. Near duplicates/subject/session/source overlaps не проверены; zero exact duplicates не independence.''', ['S025','S026'], ['W1-06-F01','W1-06-F02','W1-06-F03','W1-06-F05','W1-15-F08','W2-09-F04'])
add('Smoker: actual confusers, домен и условия', '''**Документ/targeted visual.** Search queries включают cigarette/person/coughing/inhaler/phone/drinking, но queries не доказывают actual покрытие всех действий. Из40 первых negative thumbnails: notsmoking_0091 телефон у лица,0053 телефон в руках,0120 ингалятор у рта,0041 неоднозначная рука у лица. Это наши proposed tags, не source labels или частоты; drinking/eating не объявлять подтверждёнными здесь. Web portraits/studio/crops не factory CCTV. Нет tracks/FPS/events/zones/sourceperson IDs. Card CC BY4.0, upstream поисковые photo rights не восстановлены. Conditional crop-classification/hard-negative relabel donor, не operational falsealerts/h.''', ['S025','S026'], ['W1-06-F04','W1-10-F08','W2-09-F05'])
add('Surveillance smoking: точные единицы GT/counts', '''**Документ/author counts, actual dataset не получен.** Zhang et al.2023 §3.1: indoor/outdoor videos, screen every several frames, MTCNN оставляет face-containing images. LabelMe behavior box охватывает лицо+связанные objects, labels smoking/calling/normal; отдельно hand/cigarette/phone boxes. Face coordinates automated MTCNN, не manual face GT. Не full-person и не temporal intervals. Train10,461frames:4,516smoking/3,968calling/1,977normal; object9,861hand/6,197cigarette/4,873phone. Test1,167images from other videos/webpages. Face-visibility selection ограничивает дальнюю/верхнюю/отвёрнутую камеру. Different videos не supplied subject/camera/session holdout.''', ['S027'], ['W2-09-F01','W2-09-F02'])
add('Surveillance smoking: access и event gap', '''**Документ/неизвестно.** Полный издательский PDF получен после HTML429; DataAvailability upon reasonable request to corresponding author, public dataset URL не указан. Письмо не отправлено. Article CC BY4.0 не лицензия неприсланных images/labels. Подготовленный запрос Q013: images/LabelMe map, source-video IDs/splits, license/demo/redistribution. Smoking near flammable materials, intervals/policy и continuous safe denominator не получены; не объявлять, что visual dataset вообще не существует. E012 — собственная target annotation как независимый маршрут.''', ['S027'], ['W2-09-F03'])
section('D08 — Önal/Dandıl: реальное заводское replay')
add('Önal: source cameras и 4,000h против691clips', '''**Документ/author claim.** Две UNV IPC2122CR3-PF40-A IP-камеры завода Kafaoğlu Metal Plastik Makine San. ve Tic. A.Ş.,Eskişehir; съёмка05.11–13.12.2022,около4,000hraw. Высота~4m,дневнойсвет/ночныелампы. PaperMP4/H.264/1920×1080/24FPS — документарный контракт, actual rates ниже отличаются. Published691curatedclips не4,000hдоступногоbenchmark и не operational safe denominator.''', ['S030','S031'], ['W1-07-F01','W1-13-F05'])
add('Önal: exact class map, split и manifest', '''**Документ/наш полный inventory metadata.** 691MP4entries в16leaf class/split folders,train566/test125,totaladvertised9,999,951,582bytes. Class0 Safe Walkway Violation178/32;1 Unauthorized Intervention97/11;2 Opened Panel Cover129/13;3 Carrying Overload with Forklift48/8;4 Safe Walkway50/25;5 Authorized Intervention23/15;6 Closed Panel Cover19/13;7 Safe Carrying22/8 (train/test). Имена0_tr1/0_te1 кодируютclass/split/clip. Root files пуст, interval/polygon/track/multi-label sidecars/README/license files вmanifestнет; unpublished GT этим не исключено. Статья допускает несколько behaviors в клипе.''', ['S030','S031'], ['W1-07-F02','W2-10-F01'])
add('Önal: восемь actual samples и timing', '''**Наша проверка.** Все8 H264 1920×1080, yuv420p/yuvj420p, selected JPEG extracted; UUID/bytes/SHA256 вSAMPLE_OBSERVATIONS. Clip / bytes / duration s / start s / displayedfps / tbn: 0_te23 /6391494/10.48/0/23/19672; 0_te9 /33474374/17.02/0/24.80/15872;4_te5 /4217183/10.44/0/25.10/19672;4_te19 /28558205/15.06/0/24.83/19864;0_tr128 /3021735/10.45/0/25.08/19672;0_tr16 /34584860/16.98/0.040008/24.80/15872;4_tr13 /3240413/10.41/0/25.06/19672;4_tr6 /42290441/20.84/0/25.05/16032.4_tr6 Bandicut Joiner,другие Cutter;20.84s уточняет paper1–20s. ffmpeg-i безoutput ожидаемо пишет“atleastoneoutput…”,это не decodefailure. Дляtiming использоватьtimestamps,неhardcode24/clipstart. Full691decodeне выполнен.''', ['S030'], ['W2-10-F02','W2-10-F03'])
