if __name__=='__main__':
    out=[]
    for x in facts:
        if 'section' in x: out.append('\n## '+x['section']+'\n'); continue
        src=', '.join(f'[{s}](SOURCES.md#{s.lower()})' for s in x['sources'])
        out.append(f"\n### {x['id']} — {x['title']}\n\n{x['body']}\n\nОснования: {src}. Точные первичные локаторы и границы доступа — записи SOURCES; дополнительные execution logs — соответствующая W2 card.\n")
    (ROOT/'_WORK'/'COLLECTOR_FACTS_B.json').write_text(json.dumps(facts,ensure_ascii=False,indent=2),encoding='utf-8')
    base=(ROOT/'RAW_FACTS.md').read_text(encoding='utf-8').split('\n## D03 —')[0]
    (ROOT/'RAW_FACTS.md').write_text(base+'\n'+'\n'.join(out),encoding='utf-8')
    print('Saved',sum('id' in x for x in facts),'facts; final',next(x['id'] for x in reversed(facts) if 'id' in x))
